// Cost projector: per-feature books → monthly totals (plain JS)
function projectCost(features, priceIn1k, priceOut1k, tasksPerDay) {
  return features.map((f) => {
    const perTask = (f.inTokens / 1000) * priceIn1k + (f.outTokens / 1000) * priceOut1k;
    return { name: f.name, perTask: +perTask.toFixed(4), monthly: +(perTask * tasksPerDay * 30).toFixed(2) };
  });
}
// projectCost([{name:'triage', inTokens:800, outTokens:60}], 0.005, 0.015, 1000)
// → perTask $0.0049, monthly $147: the unit economics of one feature.

// Cache key discipline: tenant + data-class + signature (plain JS)
function cacheKey(tenant, dataClass, query) {
  if (dataClass === "personal") return `t:${tenant}:q:${hash(query)}`; // NEVER shared
  if (dataClass === "public") return `public:q:${hash(query)}`;       // shared broadly
  return `t:${tenant}:policy:${hash(query)}`;                          // tenant-scoped
}
function hash(s) { let h = 0; for (const c of s) h = (h * 31 + c.charCodeAt(0)) | 0; return (h >>> 0).toString(16); }
// Personal data shares keys with NOBODY: isolation is a cache-design requirement.

