function projectCost(features, priceIn1k, priceOut1k, tasksPerDay) {
  return features.map((f) => {
    const perTask = (f.inTokens / 1000) * priceIn1k + (f.outTokens / 1000) * priceOut1k;
    return { name: f.name, perTask: Math.round(perTask * 10000) / 10000, monthly: Math.round(perTask * tasksPerDay * 30 * 100) / 100 };
  });
}
const rows = projectCost([
  { name: 'triage', inTokens: 800, outTokens: 60 },
  { name: 'draft', inTokens: 2500, outTokens: 400 },
], 0.005, 0.015, 1000);
for (const r of rows) console.log(r.name + ' perTask=$' + r.perTask + ' monthly=$' + r.monthly);
console.log('total monthly=$' + rows.reduce((s, r) => s + r.monthly, 0));

